INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'infection', 'n.', '/ɪnˈfekʃn/', '传染;感染', 'Enough sleep helps your body fight off infection.', '充足的睡眠有助于身体抵抗感染。', 'Healthy Lifestyle', 1, 0, 'senior', 'wordlist', 'required3', 'U3', 'fight off infection', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'moody', 'adj.', '/ˈmuːdi/', '脾气坏的;情绪多变的;郁郁寡欢的', 'Not getting enough sleep can make you moody.', '睡眠不足会让你情绪低落、脾气变坏。', 'Healthy Lifestyle', 2, 0, 'senior', 'wordlist', 'required3', 'U3', 'feel moody', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'motivate', 'v.', '/ˈməʊtɪveɪt/', '激励;激发;推动', 'As long as you stay motivated, you will reach your health goal.', '只要保持动力,你就会达成健康目标。', 'Healthy Lifestyle', 3, 0, 'senior', 'wordlist', 'required3', 'U3', 'stay motivated', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'classic', 'adj./n.', '/ˈklæsɪk/', '典型的;有代表性的;经典的;经典作品', 'Exercise versus more sleep is a classic health debate.', '运动还是多睡是一个典型的健康话题之争。', 'Healthy Lifestyle', 4, 0, 'senior', 'wordlist', 'required3', 'U3', 'a classic debate', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'beneficial', 'adj.', '/ˌbenɪˈfɪʃl/', '有利的;有帮助的;有用的', 'A morning workout is more beneficial than an extra hour of sleep.', '晨练比多睡一小时更有益。', 'Healthy Lifestyle', 5, 0, 'senior', 'wordlist', 'required3', 'U3', 'beneficial to health', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'depression', 'n.', '/dɪˈpreʃn/', '抑郁;抑郁症;精神忧郁', 'Regular exercise can help a person deal with depression.', '规律运动有助于一个人应对抑郁。', 'Healthy Lifestyle', 6, 0, 'senior', 'wordlist', 'required3', 'U3', 'deal with depression', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'anxiety', 'n.', '/æŋˈzaɪəti/', '焦虑;忧虑', 'A single workout can lower anxiety and stress.', '一次锻炼就能减轻焦虑和压力。', 'Healthy Lifestyle', 7, 0, 'senior', 'wordlist', 'required3', 'U3', 'reduce anxiety', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'lower', 'v.', '/ˈləʊə(r)/', '降低;使……降下;放低', 'Exercise can lower your blood pressure and improve heart health.', '运动能降低血压、改善心脏健康。', 'Healthy Lifestyle', 8, 0, 'senior', 'wordlist', 'required3', 'U3', 'lower blood pressure', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'pressure', 'n.', '/ˈpreʃə(r)/', '压力;压强;挤压', 'Working out helps keep your blood pressure under control.', '锻炼有助于控制血压。', 'Healthy Lifestyle', 9, 0, 'senior', 'wordlist', 'required3', 'U3', 'blood pressure', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'improve', 'v.', '/ɪmˈpruːv/', '改进;改善;变得更好', 'Good habits will improve your overall health over time.', '好习惯会逐渐改善你的整体健康。', 'Healthy Lifestyle', 10, 0, 'senior', 'wordlist', 'required3', 'U3', 'improve your health', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'reduce', 'v.', '/rɪˈdjuːs/', '减少;缩小;降低', 'Hand washing can reduce your chances of falling sick.', '洗手能降低你生病的几率。', 'Healthy Lifestyle', 11, 0, 'senior', 'wordlist', 'required3', 'U3', 'reduce the risk', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'extreme', 'adj.', '/ɪkˈstriːm/', '极度的;极大的', 'Fatigue means extreme tiredness that rest alone cannot cure.', '疲劳指的是仅靠休息无法消除的极度劳累。', 'Healthy Lifestyle', 12, 0, 'senior', 'wordlist', 'required3', 'U3', 'extreme tiredness', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'suffer', 'v.', '/ˈsʌfə(r)/', '受苦;遭受;蒙受', 'People who suffer from fatigue often feel more energetic after exercise.', '受疲劳困扰的人在运动后往往感觉更有精神。', 'Healthy Lifestyle', 13, 0, 'senior', 'wordlist', 'required3', 'U3', 'suffer from fatigue', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'alcohol', 'n.', '/ˈælkəhɒl/', '酒精;含酒精饮料', 'The alcohol in some hand gels can kill germs.', '一些洗手凝胶中的酒精能杀死细菌。', 'Healthy Lifestyle', 14, 0, 'senior', 'wordlist', 'required3', 'U3', 'alcohol in sanitiser', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'option', 'n.', '/ˈɒpʃn/', '选择;可选择的事物;选择权', 'Hand gel should only be a second option when soap is not available.', '在没有肥皂时,洗手液只应作为第二选择。', 'Healthy Lifestyle', 15, 0, 'senior', 'wordlist', 'required3', 'U3', 'a second option', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'rub', 'v.', '/rʌb/', '擦;搓;磨', 'Rub your hands together for twenty seconds to remove germs.', '把双手搓二十秒以去除细菌。', 'Healthy Lifestyle', 16, 0, 'senior', 'wordlist', 'required3', 'U3', 'rub your hands together', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'confirm', 'v.', '/kənˈfɜːm/', '证实;确认;证明', 'A large review confirmed that powered brushes remove more plaque.', '一项大型研究证实电动牙刷能去除更多牙菌斑。', 'Healthy Lifestyle', 17, 0, 'senior', 'wordlist', 'required3', 'U3', 'confirm the finding', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'overall', 'adj.', '/ˌəʊvərˈɔːl/', '全面的;综合的;总体的', 'Good brushing is important for your overall health, not just your teeth.', '好好刷牙对你的整体健康都很重要,不只是牙齿。', 'Healthy Lifestyle', 18, 0, 'senior', 'wordlist', 'required3', 'U3', 'overall health', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'clinic', 'n.', '/ˈklɪnɪk/', '诊所;门诊部;医疗中心', 'The doctor at the clinic told me to brush for at least two minutes.', '诊所的医生让我至少刷牙两分钟。', 'Healthy Lifestyle', 19, 0, 'senior', 'wordlist', 'required3', 'U3', 'a health clinic', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'immediately', 'adv.', '/ɪˈmiːdiətli/', '立即;马上;即刻', 'If you feel chest pain, you should see a doctor immediately.', '如果感到胸痛,你应该立即去看医生。', 'Healthy Lifestyle', 20, 0, 'senior', 'wordlist', 'required3', 'U3', 'act immediately', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'movement', 'n.', '/ˈmuːvmənt/', '运动;活动;移动', 'Even gentle movement during the day keeps your body active.', '即使是白天轻微的活动也能让身体保持活跃。', 'Healthy Lifestyle', 21, 0, 'senior', 'wordlist', 'required3', 'U3', 'gentle movement', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'stretch', 'v./n.', '/stretʃ/', '伸展;拉长;抻松', 'Stretch your muscles gently before you go jogging.', '慢跑前轻轻伸展你的肌肉。', 'Healthy Lifestyle', 22, 0, 'senior', 'wordlist', 'required3', 'U3', 'stretch your muscles', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'charge', 'n./v.', '/tʃɑːdʒ/', '掌管;负责;费用;充电', 'It is time to take charge of your health and build good habits.', '是时候掌管自己的健康、养成好习惯了。', 'Healthy Lifestyle', 23, 0, 'senior', 'wordlist', 'required3', 'U3', 'take charge of', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'source', 'n.', '/sɔːs/', '来源;源头', 'Like sugar, fat is also an important source of calories.', '和糖一样,脂肪也是热量的重要来源。', 'Healthy Lifestyle', 24, 0, 'senior', 'wordlist', 'required3', 'U3', 'a source of energy', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'energy', 'n.', '/ˈenədʒi/', '能量;精力;活力', 'Working out does not use up energy; it builds it.', '锻炼不会耗尽精力,反而会增加精力。', 'Healthy Lifestyle', 25, 0, 'senior', 'wordlist', 'required3', 'U3', 'energy levels', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'extra', 'adj.', '/ˈekstrə/', '额外的;外加的', 'Sugary drinks simply mean extra calories with little benefit.', '含糖饮料只意味着多余的热量,几乎没有益处。', 'Healthy Lifestyle', 26, 0, 'senior', 'wordlist', 'required3', 'U3', 'extra calories', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'type', 'n.', '/taɪp/', '种类;类型', 'Take control of how much and what type of food you eat.', '掌控你吃多少以及吃哪种食物。', 'Healthy Lifestyle', 27, 0, 'senior', 'wordlist', 'required3', 'U3', 'type of food', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'plate', 'n.', '/pleɪt/', '盘子;一盘(食物)', 'Try to make half of your plate fruits and vegetables.', '尽量让你盘子里一半是水果和蔬菜。', 'Healthy Lifestyle', 28, 0, 'senior', 'wordlist', 'required3', 'U3', 'fill your plate', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'replace', 'v.', '/rɪˈpleɪs/', '替换;取代;以……代替', 'Replace processed foods with fresh fruits and vegetables.', '用新鲜水果蔬菜替换加工食品。', 'Healthy Lifestyle', 29, 0, 'senior', 'wordlist', 'required3', 'U3', 'replace ... with', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'habit', 'n.', '/ˈhæbɪt/', '习惯;习性', 'Developing a new healthy habit takes time and patience.', '养成一个新的健康习惯需要时间和耐心。', 'Healthy Lifestyle', 30, 0, 'senior', 'wordlist', 'required3', 'U3', 'develop a habit', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'active', 'adj.', '/ˈæktɪv/', '积极的;活跃的;好动的', 'Simple chores can keep you active on a regular basis.', '简单的家务能让你有规律地保持活跃。', 'Healthy Lifestyle', 31, 0, 'senior', 'wordlist', 'required3', 'U3', 'stay active', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'lifestyle', 'n.', '/ˈlaɪfstaɪl/', '生活方式', 'A healthy lifestyle includes good food, exercise and enough sleep.', '健康的生活方式包括良好饮食、运动和充足睡眠。', 'Healthy Lifestyle', 32, 0, 'senior', 'wordlist', 'required3', 'U3', 'a healthy lifestyle', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'regular', 'adj.', '/ˈreɡjələ(r)/', '有规律的;定期的;经常的', 'Try to exercise on a regular basis rather than once a month.', '尽量有规律地运动,而不是一个月一次。', 'Healthy Lifestyle', 33, 0, 'senior', 'wordlist', 'required3', 'U3', 'on a regular basis', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'sugary', 'adj.', '/ˈʃʊɡəri/', '含糖的;甜的', 'We should avoid sugary drinks such as soda and sweet tea.', '我们应该避免汽水、甜茶等含糖饮料。', 'Healthy Lifestyle', 34, 0, 'senior', 'wordlist', 'required3', 'U3', 'sugary drinks', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'calorie', 'n.', '/ˈkæləri/', '卡路里;热量(单位)', 'Added sugar in drinks means a lot of extra calories.', '饮料里加的糖意味着大量额外的热量。', 'Healthy Lifestyle', 35, 0, 'senior', 'wordlist', 'required3', 'U3', 'extra calories', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'fitness', 'n.', '/ˈfɪtnəs/', '健康;健壮;(运动带来的)身体健康', 'A fitness app can help you keep track of how active you are.', '健身应用能帮你了解自己每天的活动量。', 'Healthy Lifestyle', 36, 0, 'senior', 'wordlist', 'required3', 'U3', 'a fitness app', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'goal', 'n.', '/ɡəʊl/', '目标;目的', 'Stay motivated and you will meet your health goal.', '保持动力,你就会实现健康目标。', 'Healthy Lifestyle', 37, 0, 'senior', 'wordlist', 'required3', 'U3', 'meet your goal', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'challenge', 'v./n.', '/ˈtʃælɪndʒ/', '挑战;向……发起挑战;难题', 'Challenge your friends to be healthy together with you.', '鼓励你的朋友和你一起保持健康。', 'Healthy Lifestyle', 38, 0, 'senior', 'wordlist', 'required3', 'U3', 'challenge your friends', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'increase', 'v.', '/ɪnˈkriːs/', '增加;增长;提高', 'Studies show that workouts can increase your energy levels.', '研究表明锻炼能提升你的精力水平。', 'Healthy Lifestyle', 39, 0, 'senior', 'wordlist', 'required3', 'U3', 'increase energy', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'avoid', 'v.', '/əˈvɔɪd/', '避免;避开;躲开', 'Doctors advise us to avoid sweet drinks and processed foods.', '医生建议我们避免甜饮料和加工食品。', 'Healthy Lifestyle', 40, 0, 'senior', 'wordlist', 'required3', 'U3', 'avoid sweet drinks', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'weight', 'n.', '/weɪt/', '体重;重量', 'Eating late at night may make you put on weight.', '深夜进食可能会让你长胖。', 'Healthy Lifestyle', 41, 0, 'senior', 'wordlist', 'required3', 'U3', 'put on weight', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'stress', 'n.', '/stres/', '压力;紧张;焦虑', 'People in Blue Zones often live a low-stress life.', '蓝区的人们常常过着低压力的生活。', 'Healthy Lifestyle', 42, 0, 'senior', 'wordlist', 'required3', 'U3', 'a low-stress life', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'diet', 'n.', '/ˈdaɪət/', '饮食;日常食物;节食', 'A plant-based diet with lots of colour is good for your heart.', '色彩丰富的植物性饮食对心脏有益。', 'Healthy Lifestyle', 43, 0, 'senior', 'wordlist', 'required3', 'U3', 'a plant-based diet', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'sufficient', 'adj.', '/səˈfɪʃnt/', '足够的;充足的', 'Teenagers need sufficient sleep to stay healthy and focused.', '青少年需要充足的睡眠才能保持健康和专注。', 'Healthy Lifestyle', 44, 0, 'senior', 'wordlist', 'required3', 'U3', 'sufficient sleep', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'physical', 'adj.', '/ˈfɪzɪkl/', '身体的;体力的;物理的', 'Too much sugar is harmful to your physical health.', '过多的糖对你的身体健康有害。', 'Healthy Lifestyle', 45, 0, 'senior', 'wordlist', 'required3', 'U3', 'physical health', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'mental', 'adj.', '/ˈmentl/', '心理的;精神的;智力的', 'Exercise is good for both physical and mental health.', '运动对身体和心理健康都有好处。', 'Healthy Lifestyle', 46, 0, 'senior', 'wordlist', 'required3', 'U3', 'mental health', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'advice', 'n.', '/ədˈvaɪs/', '建议;忠告', 'Amy offers advice on how to deal with health problems.', 'Amy 就如何应对健康问题提供建议。', 'Healthy Lifestyle', 47, 0, 'senior', 'wordlist', 'required3', 'U3', 'offer advice', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'balance', 'n./v.', '/ˈbæləns/', '平衡;均衡;使平衡', 'A healthy life needs a good balance of food, sleep and exercise.', '健康生活需要食物、睡眠和运动之间的良好平衡。', 'Healthy Lifestyle', 48, 0, 'senior', 'wordlist', 'required3', 'U3', 'a good balance', NULL, 'sufe');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('s3u3.01', '①并列句/简单句省略(避免重复)', 'A2', 10, '上外版必修第三册 U3 — 当 and / but / or 连接的两部分共用相同的动词、主语或成分时,后半部分把重复的词省去:I like tea and (I like) coffee;She can swim but I can''t (swim)。', 1, 'required3', 'U3', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'sufe');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('s3u3.02', '②状语从句省略(主语与主句一致且含 be)', 'A2', 10, '上外版必修第三册 U3 — when/while/if/though/as 等从句的主语与主句相同且含 be 动词时,可省略「主语+be」:when (you are) young;if (it is) necessary;though (he was) tired。', 2, 'required3', 'U3', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'sufe');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('s3u3.03', '③不定式 to 的省略 & 答语/对话省略', 'A2', 10, '上外版必修第三册 U3 — 为避免重复前面出现过的动词,只保留 to:I''d love to (go);want to / would like to 后动词省去。答语中也常省略已知信息:Yes, I''d love to。', 3, 'required3', 'U3', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'sufe');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U3' AND code='s3u3.01'), '"Xiaohan is going on a diet, but I don''t think Xiaosong ____."', 'will', 'does so', 'goes', 'is', 'A', '省去重复的 go on a diet,用助动词 will 收尾即可。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U3' AND code='s3u3.01'), '"My brother likes swimming, and ____ jogging in the morning."', 'me', 'I', 'mine', 'myself', 'B', '并列结构省去重复的动词 like,后半句主语用主格 I。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U3' AND code='s3u3.01'), '"Yihui likes reading, Lingyun likes football and Shanshan ____ gardening."', 'to like', 'liking', 'likes', 'like', 'C', '三项并列重复同一动词 like,各分句保留 likes(主语第三人称单数)。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U3' AND code='s3u3.01'), '"You''d better drink fat-free milk or ____ low-fat milk."', 'drank', 'to drink', 'drinking', 'drink', 'D', 'or 连接的并列,省去重复的情态结构,保留原形动词 drink 与前一致。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U3' AND code='s3u3.01'), '"She eats a lot of vegetables, but her brother ____."', 'doesn''t', 'isn''t', 'won''t', 'hasn''t', 'A', '省去重复的 eat a lot of vegetables,一般现在时否定用 doesn''t。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U3' AND code='s3u3.01'), '"Too much sugar is harmful to physical and ____ health."', 'the mental', 'mental', 'a mental', 'mentally', 'B', 'physical and mental health 共用一个 health,省去重复名词,形容词 mental 直接并列。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U3' AND code='s3u3.03'), '"He wanted to go to the gym, but he was too tired ____."', 'for', 'that', 'to', 'so', 'C', 'too...to 结构中省去重复的 go to the gym,只留不定式记号 to。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U3' AND code='s3u3.01'), '"I can run five kilometres, but my sister ____."', 'doesn''t', 'isn''t', 'won''t', 'can''t', 'D', '省去重复的 run five kilometres,情态动词 can 的否定用 can''t。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U3' AND code='s3u3.01'), '"Dark green, red ____ orange vegetables all have high levels of nutrients."', 'and', 'but', 'so', 'that', 'A', '三个并列形容词共用一个名词 vegetables,用 and 连接,省去重复的 vegetables。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U3' AND code='s3u3.01'), '"Some students skip meals, others eat very little, ____ a few simply fast."', 'that', 'and', 'which', 'what', 'B', '并列分句用 and 连接,后句省去重复成分,只保留新信息。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U3' AND code='s3u3.01'), '"My friends have different hobbies: Tom likes cycling and Ann ____ yoga."', 'is', 'has done', 'does', 'will', 'C', 'do yoga 的 do 不能省,省去的是重复信息;此处保留 does(第三人称单数)接 yoga。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U3' AND code='s3u3.01'), '"He looks much healthier than his cousin ____."', 'is', 'has', 'done', 'does', 'D', '比较句省去重复的 looks healthy,用助动词 does 收尾。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U3' AND code='s3u3.01'), '"We can eat out tonight, or we ____ cook something simple at home."', 'can', 'are', 'do', 'have', 'A', 'or 连接的并列省去重复的 can,后句保留情态动词 can。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U3' AND code='s3u3.01'), '"Liz drinks soda while studying, but she knows she ____."', 'isn''t', 'shouldn''t', 'doesn''t', 'won''t', 'B', '省去重复的 drink soda,情态结构否定用 shouldn''t。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U3' AND code='s3u3.01'), '"Routine chores don''t get your heart rate up the way jogging ____."', 'is', 'has', 'does', 'done', 'C', '比较中省去重复的 gets your heart rate up,用 does 替代。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U3' AND code='s3u3.01'), '"He has already exercised today, but I ____ yet."', 'didn''t', 'wasn''t', 'don''t', 'haven''t', 'D', '省去重复的 exercised,现在完成时否定用 haven''t(配 yet)。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U3' AND code='s3u3.01'), '"Mike runs faster than John ____."', 'does', 'is', 'run', 'ran', 'A', '比较句省去重复的 runs,用助动词 does 收尾。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U3' AND code='s3u3.01'), '"You should reduce salt, ____ leave it out altogether if you can."', 'that', 'or', 'which', 'what', 'B', 'or 连接两个并列建议,后句省去重复的主语 you 与 should。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U3' AND code='s3u3.01'), '"My sister got eight hours of sleep last night, but I only ____ six."', 'get', 'getting', 'got', 'to get', 'C', '并列句省去重复的 hours of sleep,保留过去式 got 接 six。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U3' AND code='s3u3.01'), '"Some people love morning workouts, ____ others prefer evening walks."', 'for', 'so', 'that', 'but', 'D', '前后形成对比,用 but 连接两个并列分句。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U3' AND code='s3u3.01'), '"She wanted to join the dance club, and her friends ____ too."', 'did', 'were', 'have', 'are', 'A', '省去重复的 wanted to join the dance club,用助动词 did 收尾。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U3' AND code='s3u3.02'), '"____ weak and tired, Yutong still went jogging in the afternoon."', 'Because', 'Though', 'Unless', 'So', 'B', '句意''虽然又弱又累,却仍去慢跑''=Though (he was) weak and tired,从句省去''he was'';让步连词用 Though。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U3' AND code='s3u3.02'), '"____ young, you should start building healthy habits early."', 'Unless', 'Because', 'When', 'So', 'C', 'When (you are) young ''当你年轻时'',时间从句省去''you are'';连词用 When。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U3' AND code='s3u3.02'), '"See a doctor immediately ____ necessary, rather than wait at home."', 'unless', 'though', 'so', 'if', 'D', 'if (it is) necessary ''如果必要'',条件从句省去''it is'';连词用 if。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U3' AND code='s3u3.02'), '"____ exercising on a regular basis, you also need enough sleep."', 'While', 'Unless', 'Because', 'So', 'A', 'While (you are) exercising ''在运动的同时'',时间从句省去''you are'';连词用 While。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U3' AND code='s3u3.02'), '"____ a classic debate, the answer is actually quite simple."', 'Because', 'Though', 'Unless', 'If', 'B', 'Though (it is) a classic debate ''尽管是个典型争论'',让步从句省去''it is'';连词用 Though。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U3' AND code='s3u3.02'), '"____ in doubt about a symptom, ask a doctor for advice."', 'Unless', 'Because', 'When', 'So', 'C', 'When (you are) in doubt ''当你有疑问时'',时间从句省去''you are'';连词用 When。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U3' AND code='s3u3.02'), '"Wash your hands ____ necessary to fight off germs."', 'because', 'though', 'so', 'whenever', 'D', 'whenever (it is) necessary ''每当有必要时'',从句省去''it is'';连词用 whenever。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U3' AND code='s3u3.02'), '"Get eight to ten hours of sleep each night ____ possible."', 'if', 'unless', 'though', 'because', 'A', 'if (it is) possible ''如果可能'',条件从句省去''it is'';连词用 if。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U3' AND code='s3u3.02'), '"____ at the gym, remember to stretch before you start."', 'Unless', 'While', 'Because', 'So', 'B', 'While (you are) at the gym ''在健身房时'',时间从句省去''you are'';连词用 While。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U3' AND code='s3u3.02'), '"____ told otherwise by a doctor, brush your teeth twice a day."', 'Because', 'Though', 'Unless', 'So', 'C', 'Unless (you are) told otherwise ''除非另有医嘱'',从句省去''you are'';否定条件用 Unless。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U3' AND code='s3u3.02'), '"____ active every day, you will find new habits much easier."', 'Unless', 'Because', 'So', 'Once', 'D', 'Once (you are) active ''一旦你每天活跃起来'',时间从句省去''you are'';连词用 Once。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U3' AND code='s3u3.02'), '"____ tired after a long day, she still made a healthy dinner."', 'Though', 'Because', 'Unless', 'So', 'A', 'Though (she was) tired ''尽管累'',让步从句省去''she was'';连词用 Though。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U3' AND code='s3u3.02'), '"____ looking for active events, sign up together with your friends."', 'Unless', 'When', 'Because', 'So', 'B', 'When (you are) looking ''当你寻找时'',时间从句省去''you are'';连词用 When。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U3' AND code='s3u3.02'), '"____ in good shape, you can enjoy many more outdoor activities."', 'Unless', 'Though', 'If', 'Because', 'C', 'If (you are) in good shape ''如果身体状态好'',条件从句省去''you are'';连词用 If。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U3' AND code='s3u3.02'), '"____ drinking water, also remember to eat plenty of fresh fruit."', 'Unless', 'Because', 'So', 'While', 'D', 'While (you are) drinking ''在喝水的同时'',时间从句省去''you are'';连词用 While。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U3' AND code='s3u3.02'), '"____ beneficial, a daily morning run can be hard to keep up."', 'Though', 'Because', 'Unless', 'So', 'A', 'Though (it is) beneficial ''尽管有益'',让步从句省去''it is'';连词用 Though。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U3' AND code='s3u3.02'), '"____ ready, you can begin the new exercise plan tomorrow."', 'Unless', 'When', 'Because', 'So', 'B', 'When (you are) ready ''当你准备好时'',时间从句省去''you are'';连词用 When。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U3' AND code='s3u3.02'), '"____ stressed, take a short walk to lower your tension."', 'Unless', 'Though', 'If', 'Because', 'C', 'If (you are) stressed ''如果你感到有压力'',条件从句省去''you are'';连词用 If。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U3' AND code='s3u3.02'), '"____ on the running machine, keep your back straight at all times."', 'Unless', 'Because', 'So', 'While', 'D', 'While (you are) on the running machine ''在跑步机上时'',时间从句省去''you are'';连词用 While。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U3' AND code='s3u3.02'), '"____ busy, try to make some time for gentle movement."', 'Even when', 'Because', 'So that', 'Unless', 'A', 'Even when (you are) busy ''即使忙碌时'',时间从句省去''you are'';连词用 Even when。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U3' AND code='s3u3.03'), '"– Would you like to join our dance club? – Yes, I''d love ____."', 'it', 'to', 'that', 'do', 'B', '答语省去重复的 join your dance club,只保留 to。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U3' AND code='s3u3.03'), '"I don''t go jogging now, but I used ____."', 'do', 'it', 'to', 'so', 'C', 'used to (go jogging),省去重复动词,保留 to。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U3' AND code='s3u3.03'), '"– Do you want to sign up for the fun run? – I''d really like ____."', 'do', 'it', 'that', 'to', 'D', 'would like to (sign up),省去重复动词,保留 to。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U3' AND code='s3u3.03'), '"She doesn''t eat much junk food now, though she used ____."', 'to', 'do', 'so', 'it', 'A', 'used to (eat much junk food),省去动词,留 to。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U3' AND code='s3u3.03'), '"– How would you like your potatoes? – ____, please."', 'Boil it', 'Boiled', 'To boil', 'Boiling them', 'B', '答语省去 I''d like them,只保留过去分词 Boiled。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U3' AND code='s3u3.03'), '"I haven''t started the new habit yet, but I''m going ____."', 'do', 'so', 'to', 'it', 'C', 'be going to (start),省去重复动词,留 to。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U3' AND code='s3u3.03'), '"– Could you brush for two minutes? – Sure, I''ll try ____."', 'do', 'it that', 'so to', 'to', 'D', 'try to (brush for two minutes),省去动词,留 to。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U3' AND code='s3u3.03'), '"– Will you exercise on a regular basis? – Yes, I promise ____."', 'to', 'do', 'so', 'it', 'A', 'promise to (exercise),省去重复动词,留 to。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U3' AND code='s3u3.03'), '"– Are you going to give up sugary drinks? – I hope ____."', 'to do', 'so', 'it', 'that', 'B', 'hope so 替代整句肯定内容,是常见的答语省略。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U3' AND code='s3u3.03'), '"– Would you mind opening the window? – Not at all, I''d be glad ____."', 'do', 'it', 'to', 'so', 'C', 'be glad to (open it),省去重复动词,留 to。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U3' AND code='s3u3.03'), '"He never used to take a nap, but now he wants ____."', 'do', 'it', 'so', 'to', 'D', 'want to (take a nap),省去重复动词,留 to。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U3' AND code='s3u3.03'), '"– Do you think you can become a super-ager? – I''d love ____."', 'to', 'do', 'it', 'that', 'A', 'would love to (become one),省去重复动词,留 to。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U3' AND code='s3u3.03'), '"– Has Liz changed her diet? – I''m afraid ____."', 'to not', 'not', 'no do', 'don''t to', 'B', 'I''m afraid not 替代否定整句,是固定的答语省略。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U3' AND code='s3u3.03'), '"You don''t have to walk every day, but it helps ____."', 'do', 'so', 'to', 'it', 'C', 'it helps to (walk every day),省去重复动词,留 to。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U3' AND code='s3u3.03'), '"– Are you joining the charity walk? – Yes, I''d be happy ____."', 'do', 'it', 'that', 'to', 'D', 'be happy to (join),省去重复动词,留 to。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U3' AND code='s3u3.03'), '"– Did Liz skip breakfast again? – No, this morning she chose not ____."', 'to', 'do', 'so', 'it', 'A', 'chose not to (skip breakfast),省去重复动词,保留 to(否定用 not to)。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U3' AND code='s3u3.03'), '"– Will you keep track of your sleep? – I''ll certainly try ____."', 'do', 'to', 'it so', 'so it', 'B', 'try to (keep track),省去动词,留 to。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U3' AND code='s3u3.03'), '"– Would you like more cabbage soup? – Yes, I ____, please."', 'do like', 'am', 'would', 'to', 'C', '答语 Yes, I would (like more),省去重复内容,保留情态动词 would。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U3' AND code='s3u3.03'), '"I don''t usually eat out, but tonight I''ve decided ____."', 'do', 'so', 'it', 'to', 'D', 'decide to (eat out),省去重复动词,留 to。', 2, 20, 'mcq');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'Plan Healthy Meals', 'Taking charge of your health often starts with what is on your plate. Try to control how much and what type of food you eat. One simple rule is to make half of your plate fruits and vegetables, and to replace processed foods with fresh ones whenever you can. Colour matters too: dark green, red and orange vegetables carry high levels of nutrients, so a plate full of colour is usually a healthy one. Drinks deserve the same care. Sweet-tasting drinks such as soda, sweet tea and some juices add a lot of sugar, and that sugar simply means extra calories with little benefit. Choose low-fat or fat-free milk instead, because fat, like sugar, is also an important source of calories. None of this asks you to give up food you enjoy. It only asks you to choose a little more wisely, meal by meal, until healthier eating becomes a habit you no longer have to think about.', '说明·健康饮食', 158, '[{"q":"What simple rule does the passage suggest for a healthy plate?","answer":"A","options":["Filling half the plate with fruits and vegetables.","Eating only meat at every meal.","Removing all colour from your food.","Skipping vegetables to save time."],"explanation":"对应 ''make half of your plate fruits and vegetables'' 的转述。"},{"q":"Why does the writer warn against sweet drinks?","answer":"B","options":["They are too expensive for students.","The sugar in them adds calories without giving real nutrition.","They are hard to find in shops.","They taste worse than water."],"explanation":"原文 ''sugar simply means extra calories with little benefit'' 的概括。"},{"q":"What is the writer''s main attitude towards healthy eating?","answer":"A","options":["Small, wiser choices can slowly become a habit.","You must give up every food you enjoy.","Only a strict diet can ever work.","Eating well is impossible for busy people."],"explanation":"末段强调 choose a little more wisely 直到成为习惯,选''逐步养成习惯''。"}]'::jsonb, '[{"word":"plate","cn":"盘子;一盘食物"},{"word":"replace","cn":"替换;以……代替"},{"word":"calories","cn":"卡路里;热量"},{"word":"source","cn":"来源"}]'::jsonb, 2, 'required3', 'U3', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'Why a Workout Beats Extra Sleep', 'When you feel tired, which is better — exercise or an extra hour of sleep? Both rest and movement matter, but experts say that an extra hour added to a full night''s sleep is not as beneficial as a morning workout. Studies have found that even a single session of exercise can make you feel happier. It helps people deal with depression, anxiety and stress, and it can lower blood pressure, improve heart health and reduce the risk of disease. There is more. Researchers once looked into the link between exercise and fatigue, that is, extreme tiredness. They were surprised to find that exercise actually helped people who suffered from fatigue, making them feel more energetic instead of more worn out. In other words, working out does not use up your energy; it builds it. So at the end of a long, tiring day, the smarter choice is often not to lie down at once, but to get moving, because you will almost always feel better after a workout than before it.', '议论·运动的益处', 172, '[{"q":"According to experts, what is better when you feel tired?","answer":"B","options":["Sleeping the whole weekend.","Doing a workout in the morning, not sleeping longer.","Skipping both rest and exercise.","Drinking strong coffee all day."],"explanation":"原文说 workout 比 extra hour of sleep 更有益,选''晨练而非多睡一小时''。"},{"q":"What did researchers find about exercise and fatigue?","answer":"C","options":["It always makes tired people more worn out.","It has no effect on tiredness at all.","It helped tired people feel more energetic.","It only works for professional athletes."],"explanation":"对应 ''exercise actually helped people who suffered from fatigue'' 的转述。"},{"q":"What does the writer mean by saying a workout ''builds'' energy?","answer":"D","options":["Exercise quickly uses up all your strength.","Exercise replaces the need for any food.","Exercise only helps in the morning.","Exercise tends to leave you with more energy, not less."],"explanation":"原文 ''does not use up your energy; it builds it'' 的解释。"}]'::jsonb, '[{"word":"beneficial","cn":"有益的"},{"word":"anxiety","cn":"焦虑"},{"word":"fatigue","cn":"疲劳"},{"word":"suffered","cn":"遭受;受困扰"}]'::jsonb, 2, 'required3', 'U3', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'Sleep and Healthy Habits', 'Getting enough sleep is just as important for staying healthy as eating well or staying active. Your body needs sleep to do well at school and work, and even to fight off infection. When you do not sleep enough, the effects show up quickly: you may become moody and easily annoyed, and small problems start to feel much bigger than they really are. For teenagers between thirteen and eighteen years old, doctors suggest eight to ten hours of sleep each night. Changing old habits, however, can be hard. Developing a new habit, such as going to bed earlier, takes time and patience, and few people get it right on the very first try. The key is to stay motivated. Start small, keep track of how you are doing, and do not give up after one difficult night. As long as you keep going, the new pattern slowly becomes natural, and one day you reach your goal almost without noticing. Good sleep, in the end, is not luck; it is a habit you build.', '说明·睡眠与习惯养成', 173, '[{"q":"What does the passage say can happen if you do not sleep enough?","answer":"A","options":["Your mood drops and you get annoyed over small things.","You instantly become much stronger.","You no longer need any food.","Your problems all disappear."],"explanation":"对应 ''you may become moody and easily annoyed'' 的转述。"},{"q":"How many hours of sleep are suggested for teenagers?","answer":"B","options":["Four to five hours.","Eight to ten hours each night.","As little as possible.","Exactly twelve hours."],"explanation":"原文给出 ''eight to ten hours of sleep each night''。"},{"q":"What is the writer''s main point about forming a new sleep habit?","answer":"C","options":["It happens easily on the first try.","It is mostly a matter of luck.","It takes time and staying motivated.","It is impossible for students to do."],"explanation":"末段强调需要时间、保持动力,选''需要时间并保持动力''。"}]'::jsonb, '[{"word":"infection","cn":"感染"},{"word":"moody","cn":"情绪低落的;脾气坏的"},{"word":"motivated","cn":"有动力的"},{"word":"goal","cn":"目标"}]'::jsonb, 2, 'required3', 'U3', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'Soap or Hand Gel?', 'Which is better at fighting germs — soap or hand gel? Many people reach for hand gel because it is quick, but experts say that washing with soap and water is still the way to go. The alcohol in some gels can indeed kill certain germs, yet a gel should really be only a second option, used when no sink is nearby. The reason is simple. Many studies have found that running your hands under water, soaping them, and then rubbing them together for about twenty seconds removes the most germs of all. Doing this regularly clearly reduces your chances of falling sick. There is one more thing worth knowing: you do not need warm or hot water for clean hands. Cool water clears just as many germs as hot water does, so there is no excuse to skip a wash because the tap runs cold. In short, good old soap, plenty of rubbing and a little patience beat almost any shortcut when it comes to keeping your hands, and you, healthy.', '议论·洗手防菌', 172, '[{"q":"What do experts recommend for fighting germs?","answer":"D","options":["Using only hand gel at all times.","Never washing your hands at all.","Wearing gloves day and night.","Cleaning the hands with soap, not just reaching for gel."],"explanation":"原文 ''washing with soap and water is still the way to go'',选''用肥皂和水洗手''。"},{"q":"How long should you rub your hands to remove the most germs?","answer":"A","options":["About twenty seconds.","About two seconds.","A full ten minutes.","No rubbing is needed."],"explanation":"对应 ''rubbing them together for about twenty seconds''。"},{"q":"What does the passage say about water temperature?","answer":"B","options":["Only boiling water can clean hands.","Cool water cleans germs just as well as hot water.","Hot water is the only safe choice.","Water temperature changes nothing about washing time."],"explanation":"原文 ''Cool water clears just as many germs as hot water'' 的转述。"}]'::jsonb, '[{"word":"germs","cn":"细菌;病菌"},{"word":"alcohol","cn":"酒精"},{"word":"option","cn":"选择"},{"word":"rubbing","cn":"搓;擦"}]'::jsonb, 2, 'required3', 'U3', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'Taking Care of Your Teeth', 'Brushing your teeth may seem like a small daily task, but it has a big effect on your overall health. A large review of many studies once confirmed that certain electric brushes remove more of the soft film on teeth than ordinary ones, and they also reduce signs of gum trouble. Yet the tool matters less than the time you spend. One helpful feature of many electric brushes is the built-in timer. Patients, a dentist explains, often do not realise how little time they spend cleaning their teeth. Proper brushing should take at least two minutes, but many people brush for less than one. Whether you brush by hand or with an electric brush, doing it well twice a day is one of the most important habits for healthy teeth. Interestingly, the benefits do not stop at your mouth. According to the same dentist, an infection in the mouth can be bad for your heart and for the flow of blood around the body. So a clean mouth, it turns out, is part of a healthy heart as well.', '说明·口腔健康', 179, '[{"q":"What did the large review confirm about certain electric brushes?","answer":"C","options":["They are worse than ordinary brushes.","They make no difference at all.","They clear away more of the film and ease gum problems.","They damage healthy teeth."],"explanation":"对应原文电动刷''去除更多软膜、减少牙龈问题''的转述。"},{"q":"How long should proper brushing take, according to the dentist?","answer":"D","options":["Less than ten seconds.","Exactly half an hour.","Only once a week.","At least two minutes."],"explanation":"原文 ''Proper brushing should take at least two minutes''。"},{"q":"Why does the dentist say a clean mouth matters beyond the teeth?","answer":"A","options":["A mouth infection can harm the heart and blood flow.","It makes brushing faster.","It saves money on toothpaste.","It has no effect on the rest of the body."],"explanation":"末段 ''an infection in the mouth can be bad for your heart and for the flow of blood'' 的转述。"}]'::jsonb, '[{"word":"confirm","cn":"证实"},{"word":"overall","cn":"整体的"},{"word":"infection","cn":"感染"},{"word":"at least","cn":"至少"}]'::jsonb, 2, 'required3', 'U3', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'Secrets of the Blue Zones', 'Blue Zones are a few special places where people tend to live longer and more healthily than almost anywhere else. Okinawa in Japan and Sardinia in Italy are two well-known examples. Scientists who study these regions have noticed that the people there share a number of simple habits rather than any single secret. Most of them eat a plant-based diet with plenty of colourful vegetables, and they rarely eat until they feel completely full. Instead, small tricks help them stop in time, such as using smaller plates and putting extra food away before sitting down. Daily movement is part of ordinary life, built into walking, gardening and housework rather than saved for the gym. Just as important is a calm, low-stress life shared with family and close friends. Many keep a small group of lifelong companions to travel through life with, people who celebrate good luck together and offer support when things go wrong. None of these habits is hard or expensive. Together, though, they may explain why life in the Blue Zones is so long and so well.', '说明·蓝区长寿生活', 179, '[{"q":"What are Blue Zones, according to the passage?","answer":"B","options":["Areas where no one ever exercises.","Regions whose people often enjoy longer, healthier lives.","Cities with the most fast food.","Regions famous only for cold weather."],"explanation":"对应开头对 Blue Zones 的定义转述。"},{"q":"How do people in Blue Zones avoid eating too much?","answer":"C","options":["They never eat any vegetables.","They only eat once a week.","They use smaller plates and put extra food away.","They count every single calorie."],"explanation":"原文 ''using smaller plates and putting extra food away'' 的转述。"},{"q":"What does the writer suggest is behind their long, healthy lives?","answer":"D","options":["One single magic secret.","Expensive medicine and gym memberships.","Pure good luck with nothing to learn.","Several simple habits working together."],"explanation":"末段强调多个简单习惯共同作用,选''多个简单习惯共同作用''。"}]'::jsonb, '[{"word":"diet","cn":"饮食"},{"word":"stress","cn":"压力"},{"word":"companions","cn":"同伴"},{"word":"movement","cn":"活动;运动"}]'::jsonb, 2, 'required3', 'U3', 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required3', 'U3', 'My New Food Diary', 'Last month I decided to take (1)____ of what I ate and started a food diary. The first thing I noticed was how many sugary (2)____ I drank every day. Each soda added a lot of (3)____ calories that I never really needed. So I began to (4)____ them with water and low-fat milk. I also tried to fill half of my (5)____ with fruits and vegetables at every meal. Dark green and orange vegetables, my mother said, are a rich (6)____ of nutrients. At first the change was not (7)____, and I often missed my favourite snacks. But as the days passed, I started to feel lighter and had more (8)____ for school. Writing everything down helped me (9)____ track of my progress. Slowly, eating well turned into a (10)____ I no longer had to think about.', 138, 2, '[{"q":"1","answer":"A","options":["charge","noise","weather","price"],"explanation":"take charge of 掌管。"},{"q":"2","answer":"B","options":["machines","drinks","tickets","gardens"],"explanation":"sugary drinks 含糖饮料。"},{"q":"3","answer":"C","options":["empty","quiet","extra","polite"],"explanation":"extra calories 多余的热量。"},{"q":"4","answer":"D","options":["sell","lose","throw","replace"],"explanation":"replace ... with 用……替换。"},{"q":"5","answer":"A","options":["plate","shop","city","song"],"explanation":"fill half of my plate 盘子一半。"},{"q":"6","answer":"B","options":["noise","source","price","market"],"explanation":"a rich source of 丰富的来源。"},{"q":"7","answer":"C","options":["loud","wet","easy","rich"],"explanation":"not easy 不容易。"},{"q":"8","answer":"D","options":["money","snow","rain","energy"],"explanation":"more energy 更多精力。"},{"q":"9","answer":"A","options":["keep","sell","lose","drop"],"explanation":"keep track of 了解动态。"},{"q":"10","answer":"B","options":["price","habit","noise","city"],"explanation":"a habit 一个习惯。"}]'::jsonb, 1, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required3', 'U3', 'Joining the Running Club', 'I used to think exercise was boring, until my friend asked me to (1)____ up for the school running club. Being active, she said, is much more (2)____ with other people. On the first evening I could barely run one kilometre, and my legs felt (3)____ tired afterwards. But the coach told us to (4)____ our muscles gently before each run, and soon the pain went away. Week by week, I noticed that running helped (5)____ my stress after a long day of study. It even seemed to (6)____ my blood pressure and make my heart stronger. Best of all, I made new friends who would (7)____ me to keep going whenever I felt lazy. Now I exercise on a regular (8)____ rather than once a month. Running has given me more (9)____, not less, and I always feel (10)____ after a workout than before it.', 146, 2, '[{"q":"1","answer":"C","options":["sell","throw","sign","lose"],"explanation":"sign up 报名。"},{"q":"2","answer":"D","options":["boring","empty","quiet","fun"],"explanation":"more fun 更有趣。"},{"q":"3","answer":"A","options":["extremely","happily","softly","politely"],"explanation":"extremely tired 极度疲惫。"},{"q":"4","answer":"B","options":["sell","stretch","drop","hide"],"explanation":"stretch our muscles 伸展肌肉。"},{"q":"5","answer":"C","options":["raise","sell","reduce","build"],"explanation":"reduce my stress 减轻压力。"},{"q":"6","answer":"D","options":["raise","sell","open","lower"],"explanation":"lower my blood pressure 降低血压。"},{"q":"7","answer":"A","options":["motivate","stop","forget","lose"],"explanation":"motivate me 激励我。"},{"q":"8","answer":"B","options":["price","basis","noise","city"],"explanation":"on a regular basis 有规律地。"},{"q":"9","answer":"C","options":["noise","trouble","energy","weight"],"explanation":"more energy 更多精力。"},{"q":"10","answer":"D","options":["worse","sadder","angrier","better"],"explanation":"feel better 感觉更好。"}]'::jsonb, 2, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required3', 'U3', 'A Two-Week Sleep Challenge', 'After weeks of late nights, I often felt (1)____ and easily annoyed in class. My teacher explained that not getting enough sleep can also make it harder to fight (2)____ infection. So I set myself a simple two-week (3)____: to go to bed an hour earlier each night. At first it was a real (4)____, because my phone was always within reach. To stay (5)____, I left it in another room and read a book instead. Doctors say teenagers like me need at (6)____ eight hours of sleep, yet I had been getting only six. By the end of the first week, I could already feel an (7)____ in my mood and focus. I also used a sleep app to keep (8)____ of how long I actually slept. The hardest part was not giving (9)____ after one bad night. But I stayed motivated, and slowly the early bedtime became a natural (10)____.', 152, 2, '[{"q":"1","answer":"A","options":["moody","rich","loud","polite"],"explanation":"feel moody 情绪低落。"},{"q":"2","answer":"B","options":["price","off","noise","city"],"explanation":"fight off infection 抵抗感染。"},{"q":"3","answer":"C","options":["shop","garden","challenge","market"],"explanation":"a challenge 一项挑战。"},{"q":"4","answer":"D","options":["holiday","joke","game","struggle"],"explanation":"a real struggle 真正的艰难。"},{"q":"5","answer":"A","options":["motivated","afraid","angry","bored"],"explanation":"stay motivated 保持动力。"},{"q":"6","answer":"B","options":["price","least","noise","first"],"explanation":"at least 至少。"},{"q":"7","answer":"C","options":["error","noise","improvement","price"],"explanation":"an improvement 改善。"},{"q":"8","answer":"D","options":["sell","lose","drop","track"],"explanation":"keep track of 了解动态。"},{"q":"9","answer":"A","options":["up","off","in","out"],"explanation":"give up 放弃。"},{"q":"10","answer":"B","options":["price","habit","noise","city"],"explanation":"a natural habit 自然的习惯。"}]'::jsonb, 3, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required3', 'U3', 'The Clean Hands Campaign', 'Our class started a ''Clean Hands'' campaign to (1)____ the spread of germs at school. Many students used to (2)____ a quick hand gel because it was fast, but our health teacher said soap and water should always be the first (3)____. The (4)____ in some gels can kill certain germs, she explained, yet washing properly removes far more. She showed us how to (5)____ our hands together for about twenty seconds under running water. Doing this every day clearly (6)____ our chances of falling sick. She also told us that cool water works just as well, so there is no need to (7)____ for hot water. To make it fun, we put up colourful posters and asked everyone to wash their hands (8)____ before lunch. Within a month, fewer classmates were (9)____ from colds. The whole campaign proved that one small (10)____ can protect a whole class.', 148, 2, '[{"q":"1","answer":"C","options":["raise","sell","reduce","open"],"explanation":"reduce the spread 减少传播。"},{"q":"2","answer":"D","options":["sell","lose","drop","reach"],"explanation":"reach for 伸手去拿(reach for a gel)。"},{"q":"3","answer":"A","options":["option","noise","price","city"],"explanation":"the first option 首选。"},{"q":"4","answer":"B","options":["noise","alcohol","price","weather"],"explanation":"the alcohol in some gels 凝胶中的酒精。"},{"q":"5","answer":"C","options":["sell","hide","rub","drop"],"explanation":"rub our hands together 搓手。"},{"q":"6","answer":"D","options":["raises","sells","opens","reduces"],"explanation":"reduces our chances 降低几率。"},{"q":"7","answer":"A","options":["wait","sell","lose","drop"],"explanation":"wait for hot water 等热水。"},{"q":"8","answer":"B","options":["never","immediately","rarely","seldom"],"explanation":"wash immediately 立即洗。"},{"q":"9","answer":"C","options":["selling","winning","suffering","buying"],"explanation":"suffering from colds 受感冒之苦。"},{"q":"10","answer":"D","options":["noise","price","city","habit"],"explanation":"one small habit 一个小习惯。"}]'::jsonb, 4, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required3', 'U3', 'Switching to an Electric Brush', 'Last year my dentist suggested that I (1)____ to an electric toothbrush. A large review, he said, had (2)____ that powered brushes remove more of the soft film on teeth than ordinary ones. I was surprised to learn how (3)____ time most people spend cleaning their teeth. Proper brushing should take at (4)____ two minutes, but I used to brush for less than one. The built-in timer became my favourite (5)____ of the new brush, gently telling me when to stop. After a few weeks, my dentist (6)____ that my gums looked much healthier. He also reminded me that good oral care matters for my (7)____ health, not just my mouth. An (8)____ in the mouth, he warned, can even be bad for the heart. Now I brush carefully twice a day and try to (9)____ my teeth properly each time. Such a small change has had a surprisingly big (10)____ on how I feel.', 155, 2, '[{"q":"1","answer":"A","options":["switch","sell","lose","drop"],"explanation":"switch to 换成。"},{"q":"2","answer":"B","options":["lost","confirmed","sold","broken"],"explanation":"had confirmed 证实。"},{"q":"3","answer":"C","options":["many","much","little","few"],"explanation":"how little time 时间多么少。"},{"q":"4","answer":"D","options":["price","noise","city","least"],"explanation":"at least 至少。"},{"q":"5","answer":"A","options":["feature","noise","price","garden"],"explanation":"favourite feature 最喜欢的功能。"},{"q":"6","answer":"B","options":["sold","confirmed","lost","broke"],"explanation":"confirmed 确认。"},{"q":"7","answer":"C","options":["loud","wet","overall","rich"],"explanation":"overall health 整体健康。"},{"q":"8","answer":"D","options":["error","noise","price","infection"],"explanation":"an infection 感染。"},{"q":"9","answer":"A","options":["clean","sell","hide","lose"],"explanation":"clean my teeth 清洁牙齿。"},{"q":"10","answer":"B","options":["noise","effect","price","city"],"explanation":"a big effect 大的影响。"}]'::jsonb, 5, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required3', 'U3', 'My Grandmother''s Long Life', 'My grandmother is ninety years old, yet she is still healthy and full of (1)____. People often ask her secret, but she just smiles and says there is no single (2)____. Like people in the so-called Blue Zones, she keeps a number of simple habits. She eats a mostly plant-based (3)____, with lots of colourful vegetables and very little meat. She rarely eats until she is completely full, using a (4)____ plate to help herself stop in time. Every morning she takes a slow walk, because gentle (5)____ keeps her body strong. She lives a calm, low-(6)____ life surrounded by family and old friends. Whenever something goes wrong, she has someone to (7)____ with it together. I think these companions are one big (8)____ why she is so happy. None of her habits is hard or (9)____. Together, though, they may explain why she has reached such a great (10)____ in good health.', 153, 2, '[{"q":"1","answer":"C","options":["noise","trouble","energy","weight"],"explanation":"full of energy 充满活力。"},{"q":"2","answer":"D","options":["price","noise","city","secret"],"explanation":"no single secret 没有单一秘诀。"},{"q":"3","answer":"A","options":["diet","machine","garden","market"],"explanation":"a plant-based diet 植物性饮食。"},{"q":"4","answer":"B","options":["loud","smaller","wet","rich"],"explanation":"a smaller plate 更小的盘子。"},{"q":"5","answer":"C","options":["noise","price","movement","error"],"explanation":"gentle movement 轻柔的活动。"},{"q":"6","answer":"D","options":["price","noise","city","stress"],"explanation":"low-stress life 低压力的生活。"},{"q":"7","answer":"A","options":["deal","sell","lose","drop"],"explanation":"deal with it 应对它。"},{"q":"8","answer":"B","options":["noise","reason","price","city"],"explanation":"one big reason 一个重要原因。"},{"q":"9","answer":"C","options":["cheap","easy","expensive","free"],"explanation":"hard or expensive 难或贵。"},{"q":"10","answer":"D","options":["noise","price","city","age"],"explanation":"such a great age 如此高龄。"}]'::jsonb, 6, 'sufe');
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U3 听力·对话 Ordering a Healthy Lunch', '上外版必修第三册 U3 · dialogue', 3, 'Mia: I''m starving. Should we just get some pizza and soda?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U3 听力·短文 Secrets of Super-agers', '上外版必修第三册 U3 · passage', 2, 'Scientists are interested in people who stay healthy at a very old age.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U3 听力·对话 Let''s Exercise Together', '上外版必修第三册 U3 · dialogue', 3, 'Anna: You look tired, Sam. Are you sleeping enough?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U3 听力·短文 A Tip for Better Sleep', '上外版必修第三册 U3 · passage', 2, 'Getting enough sleep is one of the easiest ways to stay healthy.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U3 听力·对话 At the Dentist', '上外版必修第三册 U3 · dialogue', 3, 'Dentist: How long do you usually spend brushing your teeth?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U3 听力·短文 Life in the Blue Zones', '上外版必修第三册 U3 · passage', 2, 'In a few special places, people live longer and more healthily than elsewhere.
INSERT INTO public.junior_writing_prompts (grade, topic, title_en, prompt_cn, prompt_en, requirements, min_words, max_words, sample_answer, scoring_rubric, high_sentences, error_pairs, paragraph_template, difficulty, volume, unit, publisher) VALUES (10, 'Leading a Healthy Life:Write an advice letter to ''Ask Amy''(给健康专栏写建议信)', 'Dear Liz: Advice on a Health Problem', '假设你是校报''Ask Amy''专栏的编辑。一位同学 Liz 来信说:她最近学习太忙,饮食不规律,常深夜吃披萨、薯片和汉堡,还边写作业边喝汽水,结果体重增加,十分焦虑。请用英语写一封约80—100词的回信:① 简述你理解的她的问题与可能原因;② 给出两到三条切实可行的解决办法;③ 鼓励她坚持。注意运用本单元''省略''结构使行文自然。', 'Suppose you write the ''Ask Amy'' column for your school newspaper. A reader named Liz says that, because she has been studying so hard, she has not been eating right: she eats pizza, chips and hamburgers late at night and drinks soda while doing homework, and now she has put on weight and feels anxious. Write a reply of about 80–100 words that: 1) shows you understand her problem and its likely causes; 2) offers two or three practical solutions; 3) encourages her to keep going.', '["理解问题并指出可能原因(You mentioned … One likely cause is …)","给出可行办法1(A useful suggestion would be to …)","给出可行办法2/3(It would also help if you … / Another way is to …)","鼓励坚持(Don''t worry — small changes really add up!)"]'::jsonb, 70, 100, 'Dear Liz, Thank you for writing in. You mentioned that you study so hard that you eat pizza and chips late at night and drink soda while doing homework. One likely cause of your weight gain is these extra calories from sugary drinks and snacks. A useful suggestion would be to replace soda with water and keep some fruit nearby for late-night hunger. It would also help if you went for a short walk after dinner, because exercise builds energy rather than using it up. Don''t worry — small changes really add up. Stay motivated, and you will soon feel better. Best wishes, Amy', '【15 分制】A 档(13-15):五要素齐全、组织有条理、语言准确多样;B 档(10-12):要点较全、少量错误;C 档(7-9):要点偏少、句型简单;D 档(0-6):内容不完整、错误多。', '["One likely cause of your weight gain is the extra calories from sugary drinks and snacks.","A useful suggestion would be to replace soda with water and keep some fruit nearby.","It would also help if you went for a short walk after dinner.","Don''t worry — small changes really add up."]'::jsonb, '[{"wrong":"You should eat less the junk food.","correct":"You should eat less junk food.","note":"junk food 为不可数名词,前面不加 the。"},{"wrong":"Exercise will help you to feeling better.","correct":"Exercise will help you (to) feel better.","note":"help sb (to) do sth,后接动词原形,不用 -ing。"},{"wrong":"If it necessary, see a doctor.","correct":"If (it is) necessary, see a doctor.","note":"状语从句省略须主语与主句一致且含 be,补全为 it is 或整体省略,不能只丢 is。"}]'::jsonb, '【健康建议信结构】
INSERT INTO public.junior_grammar_tips (grade, volume, unit, content, publisher) VALUES (10, 'required3', 'U3', '{"title":"省略(Ellipsis)速查","intro":"省略就是为了避免重复、让句子更简洁,把可以从上下文补全的词去掉,而句意保持完整。三大常见场合:① 并列句中重复的成分;② 状语从句中与主句一致的''主语+be'';③ 不定式只留 to、以及对话答语中的省略。","table":{"headers":["省略场合","完整 → 省略后(例句)"],"rows":[["并列(and/but/or)","I like tea and (I like) coffee;She can swim but I can''t (swim)"],["状语从句 主语+be","when (you are) young;if (it is) necessary;though (he was) tired"],["不定式留 to","I''d love to (go);I don''t now, but I used to (do)"],["答语省略","– Would you like more? – Yes, I would (like more)."]]},"specialRules":[{"rule":"状语从句省略的前提:从句主语 = 主句主语,且从句含 be 动词,才能省去''主语+be''","mark":"When (you are) young √ / When young you... ×(主语不一致就不能省)"},{"rule":"为避免重复前面的动词,不定式只保留 to;若是 be going to / used to / want to 等,也只留 to","mark":"I hope to (join) √"},{"rule":"助动词/情态动词后可直接省去重复的实义动词","mark":"He runs faster than I do;but she can''t (swim)"},{"rule":"答语中常整体省略已知信息,只留关键词:Yes, I would. / I''m afraid not. / I hope so.","mark":"答语省略"}],"why":["英语忌重复;凡是上文已出现、读者能补全的词,都可省去,使句子更简洁地道。判断能否省略,关键看''省掉的部分能否被准确还原''。"],"gaokaoPoints":["状语从句的''主语+be''省略(when/while/if/though/once/unless + 形容词/分词)是语法填空与改错高频点。","不定式 to 的省略(would love to / used to / be going to)与答语省略(Yes, I would / I''m afraid not)常考。","并列结构省略要保证''省后还原一致'':时态、主谓、句法成分都要对得上。"],"examVsReal":[{"exam":"If (it is) necessary, see a doctor.（书面省略，规范）","real":"Need a doctor? Just go.","note":"考试考''主语+be''的规范省略;真实口语更短,直接用问句或祈使句"},{"exam":"Yes, I would (like more).（答语保留情态动词）","real":"Yeah, please!","note":"考试要求答语省略后结构完整;日常口语常只用一两个词回应"}]}'::jsonb, 'sufe');
